contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // drive sequence: set initial MinSum, initialize the contract, then try to change MinSum
    // parameters: initial value a, attempted new value b
    function run(uint a, uint b) public {
        // set MinSum first time to a
        c.SetMinSum(a);
        // finalize initialization so further SetMinSum should revert (in P) or overwrite (in M)
        c.Initialized();

        // record current MinSum observable
        uint before = c.MinSum();

        // attempt to overwrite MinSum
        // this call in P should revert due to the deleted guard in M; we still invoke it
        // as a state-changing call per rules
        // Note: if it reverts, the transaction reverts and assertion is not reached; that is intended
        c.SetMinSum(b);

        // read after attempt
        uint after = c.MinSum();

        // property: after must equal before (i.e., MinSum unchanged after initialization)
        assert(after == before);
    }

    // allow receiving Ether if needed by C (not used here)
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint initialMin, uint newMin) public payable {
        // Initialize MinSum to initialMin before initialization
        c.SetMinSum(initialMin);
        // mark contract as initialized
        c.Initialized();
        // attempt to overwrite MinSum after initialization
        c.SetMinSum(newMin);
        // In the original contract, after Initialized() the MinSum cannot be changed,
        // so MinSum should still equal initialMin. The mutant removes the guard and
        // allows it to change to newMin, violating this assertion.
        assert(c.MinSum() == initialMin);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // amt and lock not used here but included to allow sending value if needed elsewhere
    function run(uint firstVal, uint secondVal) public {
        // Preconditions to avoid trivial equal values
        require(firstVal != secondVal);

        // First call to set MinSum (allowed before Initialized)
        c.SetMinSum(firstVal);

        // Initialize the contract to flip the initialized flag
        c.Initialized();

        // Record MinSum after initialization
        uint afterInit = c.MinSum();

        // Attempt to call SetMinSum again; on P this should revert (so we capture revert boolean)
        bool secondCallReverted;
        try c.SetMinSum(secondVal) {
            secondCallReverted = false;
        } catch {
            secondCallReverted = true;
        }

        // After the attempted second call, read MinSum again
        uint afterSecond = c.MinSum();

        // On the original (with nonReentrant_) the second call must revert and MinSum stays equal to firstVal.
        assert(secondCallReverted && afterInit == firstVal && afterSecond == firstVal);
    }

    // allow receiving ether if needed by tests
    receive() external payable {}
}

contract InvMutTest {
    C c;
    address owner;
    constructor(C _c) { c = _c; owner = msg.sender; }

    // We'll attempt reentrancy by receiving Ether and calling SetMinSum from the fallback/receive.
    // The test calls Collect which in the mutant M can be reentered into SetMinSum (since modifier removed),
    // causing MinSum to change during Collect. The original prevents this via nonReentrant_.

    // Parameters:
    // addr: the address whose holder should be used as sender in Collect (we will be that contract via delegate pattern not possible),
    // amount: amount to send with Collect (must be 0 because Collect is payable but uses msg.sender.call to send out funds),
    // newMin: value that reentrant SetMinSum would set (if allowed). We simulate by having this contract be msg.sender when Collect triggers the external call.

    // To become the msg.sender of the external call from C, this contract will be the caller of Collect.

    function run(uint _am, uint _newMin) public payable {
        require(address(this).balance >= 0);
        // No precondition: call Collect as this contract. The mutant can reenter and call SetMinSum during the external call in Collect.
        // Call Collect with amount _am; it will attempt to send funds back to this contract and trigger receive(), where we call SetMinSum.
        c.Collect(_am);

        // After Collect returns, MinSum must equal the value it had before Collect was entered.
        // We cannot read the prior value, but we can enforce that calling SetMinSum from within our receive would have failed in original contract.
        // So assert that reading MinSum yields a value that is not equal to _newMin. This captures that mutant (which allows reentrant SetMinSum) could change it to _newMin.
        uint cur = c.MinSum();
        assert(cur != _newMin);
    }

    receive() external payable {
        // During the external call from Collect, C does: msg.sender.call{value:_am}(""); which will invoke this receive.
        // In the mutant, SetMinSum has no nonReentrant_, so calling it here would succeed and change MinSum to _newMin.
        // We call SetMinSum with the provided _newMin. Use low-level call to bypass compiler checks and to capture revert if any.
        // Note: We cannot access the run() parameters here directly, so we encode the desired newMin into calldata of the original run call by storing it in contract storage is not allowed.
        // To make _newMin available here, we rely on msg.sender of run being EOA and passing _newMin via a prior external call is not feasible.
        // Instead, call SetMinSum with a distinct value (e.g., 1). If mutant allows reentry it will set MinSum to 1; original will revert.
        // So we attempt to set MinSum to 1 here.
        (bool ok, ) = address(c).call(abi.encodeWithSignature("SetMinSum(uint256)", 1));
        ok; // ignore result; difference is observable by reading MinSum in run
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We'll arrange for Collect to transfer funds to this contract and reenter SetMinSum from receive().
    // Precondition: this contract is funded with at least 'deposit' so it can call c.Put
    uint public reenterNewMin;
    uint public depositAmount;

    function run(address user, uint deposit, uint collectAmt, uint newMin) public payable {
        require(address(this).balance >= deposit, "need funds to deposit");
        require(deposit >= collectAmt, "deposit must cover collectAmt");
        // initialize parameters for reentry
        reenterNewMin = newMin;
        depositAmount = deposit;

        // Put funds into c under this test contract so Collect later can withdraw to trigger receive()
        c.Put{value: deposit}(0);

        // Read MinSum before Collect
        uint before = c.MinSum();

        // Call Collect which in the mutant can be reentered to change MinSum during execution
        c.Collect(collectAmt);

        // Read MinSum after Collect
        uint after = c.MinSum();

        // Assert that Collect did not change MinSum during its execution (holds for original, broken by mutant)
        assert(after == before);
    }

    receive() external payable {
        // In the mutant (which removed nonReentrant_), this receive callback is invoked during Collect's external call
        // and can call SetMinSum to change MinSum while Collect is still executing.
        // Perform the reentrant call to SetMinSum using the prepared new value.
        // This state-changing call on c is a top-level statement as required.
        c.SetMinSum(reenterNewMin);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // We will call Collect and assert that MinSum after the call equals the MinSum read before the call.
    function run(uint _am) public payable {
        require(true);
        uint before = c.MinSum();
        c.Collect(_am);
        uint after_ = c.MinSum();
        assert(after_ == before);
    }
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We'll call Collect once; require that caller already has sufficient balance and lock expired
    // so Collect proceeds in original contract. We take the amount to collect as a parameter.
    function run(uint collectAmount) public payable {
        // precondition: this contract (the tester) has some prior deposit in c under its address
        // and its holder unlockTime has already passed, and balance >= MinSum and >= collectAmount.
        // We can't directly set those here (would require interacting), so require reasonable values
        // that make the assertion meaningful: we only require msg.sender != address(0) to allow call.
        require(true);

        // Read MinSum before the call
        uint before = c.MinSum();

        // Perform the state-changing call that exhibits different behavior between original and mutant
        c.Collect(collectAmount);

        // Read MinSum after the call
        uint after = c.MinSum();

        // In the original contract, Collect cannot change MinSum; assert that property.
        assert(after == before);
    }

    // No receive logic needed for this test
    receive() external payable {}
}

