pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Attacker attacker;

    function setUp() public { c = new C(); }

    // fuzz parameters: initialMin (value to set via SetMinSum), putAmt (amount to fund and later collect), collectAmt
    function testFuzz_property(uint256 initialMin, uint256 putAmt, uint256 collectAmt) public {
        // keep amounts within reasonable bounds but wide
        initialMin = bound(initialMin, 0, 1 ether);
        putAmt = bound(putAmt, 1 wei, 1 ether);
        collectAmt = bound(collectAmt, 1 wei, 1 ether);

        // deploy attacker that will reenter Collect by calling back into SetMinSum during receive
        attacker = new Attacker(address(c));

        // initialize contract: set LogFile to attacker (harmless) and set MinSum
        // Both calls are nonReentrant_ in reference; mutant removed guard on SetMinSum only
        vm.prank(address(this));
        c.SetLogFile(address(attacker));

        vm.prank(address(this));
        c.SetMinSum(initialMin);

        // record MinSum as seen after setup
        uint256 before = c.MinSum();

        // fund attacker externally so it can call Put via fallback and set up balance
        vm.deal(address(attacker), putAmt);

        // attacker will call Put to deposit its balance into c and set unlockTime to past so Collect can proceed
        vm.prank(address(attacker));
        attacker.doPut{value: putAmt}(0);

        // now attacker will attempt to Collect; in its receive it will reenter SetMinSum to try to change MinSum
        // Poison the conditions so Collect will send funds to attacker: ensure holder.balance >= MinSum and >= collectAmt and unlockTime in past
        // We're using attacker to call Collect so reentrancy originates from receive
        vm.prank(address(attacker));
        try c.Collect{value: 0}(collectAmt) {
            // success
        } catch {
            // ignore revert; we only observe MinSum after call attempt
        }

        // Single assertion: on the correct (reference) contract MinSum must still equal the original value set
        assertTrue(c.MinSum() == before);
    }
}

// Adversarial helper: attacker that re-enters SetMinSum during receive
contract Attacker {
    address public target;
    bool public reentered;

    constructor(address _t) payable {
        target = _t;
    }

    // helper to call Put on target
    function doPut(uint _lockTime) external payable {
        // forward call to target fallback which calls Put
        (bool s,) = address(target).call{value: msg.value}("");
        require(s);
    }

    // fallback / receive used when Collect sends ETH to this contract
    receive() external payable {
        if (!reentered) {
            reentered = true;
            // attempt to re-enter SetMinSum with a different value (e.g., 1 wei) to try to change MinSum if nonReentrant_ removed
            // use low-level call to avoid compile-time checks
            (bool ok, ) = address(target).call(abi.encodeWithSignature("SetMinSum(uint256)", 1));
            // ignore result
            ok;
        }
    }
}

