pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz parameters: attacker initial deposit, collect amount, and a candidate new MinSum value
    function testFuzz_property(uint256 deposit, uint256 collectAmt, uint256 newMin) public {
        // keep values in reasonable ranges to avoid trivial overflows and keep test broad
        deposit = bound(deposit, 1, 1 ether);
        collectAmt = bound(collectAmt, 1, deposit);
        newMin = bound(newMin, 0, 1 ether);

        // deploy attacker which will reenter SetMinSum during Collect
        Attacker attacker = new Attacker(address(c));

        // initialize contract: set MinSum to some known value (use newMin as the intended new value to attempt change)
        // We must call SetMinSum through a normal externally owned account (the test) to set initial MinSum
        c.SetMinSum(0);

        // register LogFile and mark initialized via functions that require nonReentrant_ (safe to call now)
        // set LogFile to address(this) is not necessary; skip. Instead just mark initialized to allow operations later
        c.Initialized();

        // fund the attacker and have attacker deposit into c by calling fallback which routes to Put(0)
        vm.deal(address(attacker), deposit);
        attacker.fundAndPut{value: deposit}(collectAmt);

        // ensure MinSum is set to a known baseline before Collect. Use SetMinSum again from test (will revert in buggy if initialized true, so reset by creating fresh contract would be required, but per reference SetMinSum requires not initialized; we already called Initialized(), so instead we must set MinSum before Initialized)
        // To satisfy reference behavior for all inputs, redo: deploy fresh contract to set MinSum then mark initialized and perform actions.
        // Re-deploy c so ordering is correct
        c = new C();
        c.SetMinSum(0);
        c.SetLogFile(address(0));
        c.Initialized();

        // create attacker bound to this new c and fund
        attacker = new Attacker(address(c));
        vm.deal(address(attacker), deposit);
        attacker.fundAndPut{value: deposit}(collectAmt);

        // Now set MinSum to a baseline value via test (must be done before Initialized, so we need a fresh contract again)
        // Create final fresh contract where we set MinSum, do not call Initialized yet because SetMinSum only allowed when not initialized
        C c2 = new C();
        c2.SetMinSum(0);
        c2.SetLogFile(address(0));
        // Do NOT call Initialized() so SetMinSum remains callable only by non-reentrant reference; but Collect requires accounts to exist and unlockTime, so we will go through Attacker using c2

        // deploy attacker against c2 and fund
        Attacker attacker2 = new Attacker(address(c2));
        vm.deal(address(attacker2), deposit);
        attacker2.fundAndPut{value: deposit}(collectAmt);

        // Now set MinSum to a baseline value X via test while still not initialized
        uint256 baseline = 123; // small constant baseline is fine as we fuzz other values
        c2.SetMinSum(baseline);

        // Now mark as initialized so subsequent SetMinSum would revert in reference; but mutant removed nonReentrant_ so reentrant SetMinSum from attacker during Collect could change it
        c2.Initialized();

        // The attacker will try to reenter SetMinSum on c2 during Collect by calling back into SetMinSum. Pass the newMin candidate to attacker so it will attempt to set MinSum to newMin during reentry.
        attacker2.setTargetNewMin(newMin);

        // perform Collect from attacker2 (which will trigger reentrancy during the payable low-level call)
        // ensure attacker2 has deposited and unlocked balance so Collect path executes sending value to attacker2
        // the Attacker sets its own unlockTime to past via Put(0) so Collect condition block.timestamp>unlockTime holds
        bool ok;
        try c2.Collect(collectAmt) { ok = true; } catch { ok = false; }

        // The universal property: after Collect, MinSum remains equal to baseline for the reference contract
        // For the mutant (without nonReentrant_), attacker reentering SetMinSum may change MinSum to newMin for some inputs; thus the single assert reads c2.MinSum() and requires it equals baseline
        assertTrue(c2.MinSum() == baseline);
    }
}

// Adversarial reentrant attacker: when receiving Ether during Collect it will call back into SetMinSum on target
contract Attacker {
    address public target;
    uint256 public newMin;

    constructor(address _t) payable {
        target = _t;
    }

    function setTargetNewMin(uint256 _m) public { newMin = _m; }

    // helper to deposit into target via fallback -> Put(0)
    function fundAndPut(uint256 /*collectAmt*/) public payable {
        // call fallback of target which routes to Put(0)
        (bool s,) = target.call{value: msg.value}("");
        require(s);
    }

    receive() external payable {
        // during Collect, target will call us; reenter SetMinSum to attempt to change MinSum
        // ignore revert of SetMinSum: mutant will allow it, reference will revert or be protected
        (bool s,) = target.call(abi.encodeWithSignature("SetMinSum(uint256)", newMin));
        s; // silence
    }
}

