pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz parameters: attackerFunds (amount attacker deposits), setVal (value to set MinSum), collectAmt (amount to collect)
    function testFuzz_property(uint256 attackerFunds, uint256 setVal, uint256 collectAmt) public {
        // keep amounts in a reasonable wide range but non-zero where needed
        attackerFunds = bound(attackerFunds, 1, 1 ether);
        collectAmt = bound(collectAmt, 0, 1 ether);
        // deploy attacker that will reenter and call SetMinSum during Collect
        Attacker atk = new Attacker(address(c));

        // initialize MinSum via SetMinSum through the attacker (any caller allowed)
        // ensure contract not yet initialized
        vm.prank(address(this));
        c.SetMinSum(setVal);

        // fund attacker so it can Put and trigger Collect
        vm.deal(address(atk), attackerFunds);

        // attacker calls Put to set its balance and unlockTime small (0)
        vm.prank(address(atk));
        atk.doPut{value: attackerFunds}(0);

        // ensure attacker balance in c is >= MinSum and >= collectAmt; if not, skip (admissible domain)
        // we only require attackerFunds >= setVal and attackerFunds >= collectAmt for the scenario to be relevant
        vm.assume(attackerFunds >= setVal);
        vm.assume(attackerFunds >= collectAmt);

        // set attacker to attempt to reenter SetMinSum and change MinSum to a different value during Collect
        // pick a different value to set, e.g., setVal ^ 1 (flip one bit) to avoid hard-coding a constant
        uint256 newVal = setVal ^ 1;
        atk.configureReentry(newVal);

        // now have attacker call Collect; attacker will reenter SetMinSum during the low-level call if mutant allows
        bool ok;
        try atk.doCollect(collectAmt) {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property (single assertion): after Collect attempt, MinSum must still equal the originally set value
        // Reference (with nonReentrant_) guarantees this for all admissible inputs above; mutant (without nonReentrant_) can break it
        assertTrue(c.MinSum() == setVal);
    }
}

// Minimal attacker that reenters SetMinSum during Collect via its receive()
contract Attacker {
    C public target;
    uint256 public reentryVal;
    bool public configured;

    constructor(address _t) {
        target = C(_t);
    }

    // configure which value to set during reentry
    function configureReentry(uint256 v) public {
        reentryVal = v;
        configured = true;
    }

    // call Put on target
    function doPut(uint _lockTime) external payable {
        target.Put{value: msg.value}(_lockTime);
    }

    // call Collect on target; this will trigger receive() when target sends Ether back
    function doCollect(uint _am) external {
        target.Collect(_am);
    }

    // fallback/receive will be invoked when Collect sends Ether to this contract
    receive() external payable {
        // only attempt reentry once and only if configured
        if (configured) {
            configured = false; // ensure single reentry to avoid loops
            // reenter SetMinSum to change MinSum during Collect (mutant allows this)
            // ignore failure to avoid reverting the outer call in reference
            try target.SetMinSum(reentryVal) {
            } catch {
            }
        }
    }
}

