pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz params: initially set min sum, funding amount, attacker's new min value, lock time
    function testFuzz_property(uint256 initialMin, uint256 fundAmt, uint256 attackerSetMin, uint256 lockTime) public {
        // keep values in reasonable ranges but wide
        initialMin = bound(initialMin, 1, type(uint256).max/4);
        fundAmt = bound(fundAmt, 1, type(uint256).max/4);
        attackerSetMin = bound(attackerSetMin, 0, type(uint256).max/4);
        lockTime = bound(lockTime, 0, 10000);

        // deploy adversarial helper that re-enters SetMinSum during Collect via fallback
        Attacker attacker = new Attacker(address(c), attackerSetMin);

        // set MinSum initially
        c.SetMinSum(initialMin);

        // initialize the Log file so Put/Collect can call Log.AddMessage without revert
        // deploy a LogFile from the original and set it
        LogFile log = new LogFile();
        c.SetLogFile(address(log));

        // initialize contract so SetMinSum/SetLogFile cannot be called again (matches intended flow)
        c.Initialized();

        // fund attacker so it can call Collect and receive refunds and also trigger fallback
        vm.deal(address(attacker), fundAmt);

        // have attacker put funds into c (via its fallback which calls Put) and then call Collect
        // attacker will call Collect and during the external send in Collect, its fallback/receive will reenter SetMinSum
        // ensure attacker had deposited enough balance to satisfy MinSum on reference so Collect path proceeds
        vm.prank(address(attacker));
        // call Put directly by sending funds to contract via fallback of C
        (bool sent,) = address(c).call{value: fundAmt}(abi.encodeWithSignature(""));
        require(sent);

        // record MinSum before Collect
        uint256 before = c.MinSum();

        // have attacker call Collect; use try/catch to allow for both behaviors
        bool ok;
        try c.Collect{value:0}(fundAmt) {
            ok = true;
        } catch {
            ok = false;
        }

        // After Collect completes on the reference contract, MinSum must remain equal to before for all inputs
        // (the single assertion required). The mutant that removed nonReentrant_ from SetMinSum can be reentered
        // during Collect and change MinSum, causing this assertion to fail for some fuzzed inputs.
        assertTrue(c.MinSum() == before);
    }
}

// Minimal helper attacker that will re-enter SetMinSum during Collect when receiving ether
contract Attacker {
    address public target;
    uint256 public newMin;
    bool public didReenter;

    constructor(address _t, uint256 _newMin) payable {
        target = _t;
        newMin = _newMin;
        didReenter = false;
    }

    // fallback will be invoked when Collect sends ether to msg.sender
    fallback() external payable {
        // only reenter once to attempt to change MinSum
        if (!didReenter) {
            didReenter = true;
            // call SetMinSum on target to try to change it while Collect is in-flight
            C(target).SetMinSum(newMin);
        }
    }
}

// Re-declare LogFile type to be able to deploy one for setup
contract LogFile {
    struct Message { address Sender; string Data; uint Val; uint Time; }
    Message[] public History;
    Message LastMsg;
    function AddMessage(address _adr,uint _val, string memory _data) public {
        LastMsg.Sender = _adr;
        LastMsg.Time = block.timestamp;
        LastMsg.Val = _val;
        LastMsg.Data = _data;
        History.push(LastMsg);
    }
}

