        // Now trigger Collect from attacker; attacker will reenter into SetMinSum during the external call
        // Use try/catch to allow either success or revert — we only assert on MinSum after the call.
        bool ok;
        try c.Collect{value: 0}(uint256(1 ether)) {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property: in the correct contract, MinSum must remain equal to initialMin after Collect
