// Attacker receives external AddMessage calls from C (Log.AddMessage) and reenters SetMinSum during that call
contract Attacker {
    address target;
    uint256 newMin;
    constructor(address _t, uint256 _newMin) payable {
        target = _t;
        newMin = _newMin;
    }

    // mimic LogFile.AddMessage signature
    // When C calls Log.AddMessage(...), this function will be invoked and will attempt to reenter SetMinSum
    function AddMessage(address, uint256, string memory) public {
        // reenter SetMinSum on target
        // use low-level call to avoid needing ABI match; call will revert in mutant if reentrancy breaks but that's fine
        C(target).SetMinSum(newMin);
    }

    // fallback to accept Ether if sent
    fallback() external payable {}
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function
    // params: minSum to set, lockTime for Put, putAmount to fund Put, collectAmount to attempt Collect
    function runTest(uint _minSum, uint _lockTime, uint _putAmount, uint _collectAmount) public payable {
        // preconditions: this contract must have enough balance to forward put amount
        require(address(this).balance >= _putAmount);

        // Initialize c: set MinSum and set LogFile and flip Initialized so subsequent nonReentrant_ checks are active
        // These calls are required to make contract functional; they must be top-level state-changing calls.
        c.SetMinSum(_minSum);
        c.SetLogFile(address(0));
        c.Initialized();

        // Record balance of c and this contract before Put
        uint beforeC = address(c).balance;
        uint beforeAcc = c.Acc(address(this)).balance;

        // Perform Put with provided ether amount (forward value)
        c.Put{value: _putAmount}(_lockTime);

        // Now attempt Collect of _collectAmount
        // Record c balance after Put and Acc balance after Put
        uint afterPutC = address(c).balance;
